```dart
import 'package:collection/collection.dart';

List<Transaction> getTopCoinsWithHighestAverageProfit(List<Transaction> transactions) {
  final groupedTransactions = transactions.groupBy((t) => t.coinName);

  return groupedTransactions.entries
      .map((e) => e.value.reduce((a, b) => a + b))
      .map((total) => MapEntry(total.coinName, total.reduce((a, b) => a + b)))
      .toList()
      .sort((a, b) => b.value.compareTo(a.value))
      .take(3);
}

List<Transaction> getTopCoinsWithHighestAverageLoss(List<Transaction> transactions) {
  final groupedTransactions = transactions.groupBy((t) => t.coinName);

  return groupedTransactions.entries
      .map((e) => e.value.reduce((a, b) => a - b))
      .map((total) => MapEntry(total.coinName, total.reduce((a, b) => a - b)))
      .toList()
      .sort((a, b) => a.value.compareTo(b.value))
      .take(3);
}
```

