```javascript
function postMessageToSlack(text, channel) {
  const webhookUrl = `https://hooks.slack.com/services/XXXX/YYYY/ZZZZ`; // Replace with your webhook URL
  const payload = {
    "channel": channel,
    "text": text
  };
  fetch(webhookUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(payload)
  })
  .then(response => response.json())
  .then(data => console.log('Message posted to Slack:', data))
  .catch(error => console.error('Error posting message to Slack:', error));
}
```
Make sure to replace `XXXX`, `YYYY`, and `ZZZZ` with your actual Slack webhook URL.

