To achieve this, you will need to use an Arduino Uno or compatible board and connect the LED strip to the appropriate pins. Here's a simple code snippet to get you started:

```cpp
#include <Adafruit_NeoPixel.h>

const int buttonPin = 2; // Assuming your button is connected to pin 2
const int ledStripPin = 3; // Assuming your LED strip is connected to pin 3

Adafruit_NeoPixel ledStrip(60, ledStripPin); // Initialize the LED strip with 60 pixels

int currentLed = 0;
bool buttonPressed = false;

void setup() {
  ledStrip.begin();
  pinMode(buttonPin, INPUT_PULLUP);
}

void loop() {
  if (digitalRead(buttonPin) == LOW) {
    buttonPressed = true;
  }

  if (buttonPressed) {
    for (int i = currentLed; i < 60; i++) {
      ledStrip.setPixelColor(i, Wheel((i % 60) * 256 / 60));
      ledStrip.show();
      delay(100);
    }
    currentLed = 60;
    buttonPressed = false;
  }
}

// Function to generate a rainbow color
uint32_t Wheel(byte wheelPos) {
  wheelPos = (wheelPos * 64) % 256;
  return ledStrip.Color(255 - wheelPos, wheelPos, 0);
}
```

