class ProfessionalAccessPermissionsGuard {
  constructor() {}

  canActivate(context) {
    const request = context.switchToHttp().getRequest();
    const user = request.user;

    if (!user || !user.roles) {
      return false;
    }

    const permissions = ['permission1', 'permission2', 'permission3'];

    return permissions.every(permission => user.roles.includes(permission));
  }
}
