Here's a simple Graph Neural Network (GNN) using PyTorch Geometric for classification on a graph. This GNN takes in graph data with node features and edge features as input, where the node features are image-like objects with shape (Channels x Height x Width).

```python
import torch
from torch_geometric.nn import GCNConv, GATConv, GraphPool, global_mean_pool
from torch_geometric.data import DataLoader

class GNN(torch.nn.Module):
    def __init__(self, num_features, hidden_channels, num_classes, gcn_conv=True, gat_conv=False, pooling=False):
        super(GNN, self).__init__()

        if gcn_conv:
            self.gcn_conv = GCNConv(num_features, hidden_channels)
        else:
            self.gcn_conv = None

        if gat_conv:
            self.gat_conv = GATConv(num_features, hidden_channels)
        else:
            self.gat_conv = None

        self.pooling = pooling
        if pooling:
            self.pool = GraphPool(hidden_channels, True)
        else:
            self.pool = None

