Here's a decorator for Nest.js middleware that checks the `NODE_ENV` variable and returns `false` if it's not set to `true`.

```typescript
import { Injectable, CanActivate, ExecutionContext } from '@nestjs/common';

@Injectable()
export class EnvironmentGuard implements CanActivate {
  canActivate(context: ExecutionContext): boolean {
    const req = context.switchToHttp().getRequest();
    return req.env === 'true';
  }
}
```

To use this guard, you can apply it to your middleware function like this:

```typescript
import { MiddlewareFunction, Injectable } from '@nestjs/common';
import { EnvironmentGuard } from './environment.guard';

@Injectable()
export class MyMiddleware implements MiddlewareFunction {
  use(req: Request, res: Response, next: NextFunction) {
    if (req.env !== 'true') {
      return res.status(403).json({ error: 'Forbidden' });
    }
    next();
  }
}
```

In this example, the `MyMiddleware` function will only be executed if the `NODE_ENV` variable is set to `true`. If it's not, the function will return a `403 Forbidden` response.

