Here's a simple example of a toast notification using React context:

1. First, create a `ToastContext` file to define the context:

```javascript
import React, { createContext, useReducer } from 'react';

const initialState = {
  showToast: false,
  toastMessage: '',
};

const toastReducer = (state, action) => {
  switch (action.type) {
    case 'SHOW_TOAST':
      return { ...state, showToast: true, toastMessage: action.message };
    case 'HIDE_TOAST':
      return { ...state, showToast: false, toastMessage: '' };
    default:
      return state;
  }
};

export const ToastContext = createContext();

function ToastProvider({ children }) {
  const [state, dispatch] = useReducer(toastReducer, initialState);

  function showToast(message) {
    dispatch({ type: 'SHOW_TOAST', message });
  }

  function hideToast() {
    dispatch({ type: 'HIDE_TOAST' });
  }

  return (
    <ToastContext.Provider value={{ showToast, hideToast, state }}>
      {children}
    </ToastContext.Provider>
  );
}

export default ToastProvider;
```

2. Next, create a `Toast` component to display the toast notification:

```javascript
import React from 'react';
import { ToastContext } from './ToastContext';

function Toast() {
  const { showToast, toastMessage } = React.useContext(ToastContext);

  if (!showToast) {
    return null;
  }

  return (
    <div className="toast">
      {toastMessage}
      <button onClick={() => ToastContext.hideToast()}>Close</button>
    </div>
  );
}

export default Toast;
```

