Here's a PowerShell script that recursively checks folders for ACLs referring to SIDs found only in the SIDHistory of users or groups in the domain:

```powershell
# Define the domain name
$domain = "your_domain_name"

# Define the folder path to start the search from
$startFolder = "C:\Path\To\Your\StartFolder"

# Function to check if an SID is present in the SIDHistory of any user or group in the domain
function IsSidInSIDHistory($sid) {
    $domainUsers = Get-ADUser -Filter {Domain -eq $domain} -Properties MemberOf | Select-Object -ExpandProperty MemberOf
    foreach ($group in $domainUsers) {
        if (Get-ADGroupMember -Identity $group -Recursive | Where-Object { $_.SamAccountName -eq $sid }) {
            return True
        }
    }
    return False
}

# Recursively check folders for ACLs with SIDs in the SIDHistory
function CheckFolderACLs($folderPath) {
    Get-Acl -Path $folderPath | ForEach-Object {
        foreach ($access in $_.Access) {
            if ($access.IdentityReference -match "(?i)$sid") {
                if (IsSidInSIDHistory($access.IdentityReference)) {
                    Write-Host "SID $access.IdentityReference found in SIDHistory of a user or group in the domain."
                } else {
                    Write-Host "SID $access.IdentityReference not found in SIDHistory of a user or group in the domain."
                }
            }
        }
    }
    Get-ChildItem -Path $folderPath -Directory | ForEach-Object {
        CheckFolderACLs($_.FullName)
    }
}

# Start the search
CheckFolderACLs($startFolder)
```

Replace `"your_domain_name"` with your actual domain name and `"C:\Path\To\Your\StartFolder"` with the starting folder path you want to search from.
